/* Family planning and navigation. Research records remain immutable. */
(() => {
'use strict';
window.ATLAS_EXPERIENCE_VERSION=53;
const data=window.STEM_DATA, events=data.events, schools=data.schools, profiles=data.league_guide.profiles;
const q=s=>document.querySelector(s), qa=s=>Array.from(document.querySelectorAll(s));
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='stemAtlasFamilyTrack.v1';
const goals={season:{name:'Выступить в сезоне',icon:'trophy',intro:'Одна основная лига, устойчивый наставник и самостоятельная роль ребёнка.'},skills:{name:'Углубить навыки',icon:'compass',intro:'Выбрать задачу сложнее уже освоенной, проверить пробелы и собрать работающий проект.'},camp:{name:'Выбрать каникулы',icon:'sun',intro:'Конкретная смена, подходящий возраст, технический язык и содержательный проект.'},school:{name:'Найти школу и команду',icon:'book',intro:'Места обоим, младший тренер, доступ к лаборатории и полная стоимость семейного года.'}};
const tracks={robot:{name:'Робототехника',theme:['robotics'],description:'Механика → датчики → автономная миссия',color:'orange'},ai:{name:'Код и ИИ',theme:['coding','ai','games'],description:'Алгоритм → данные → проверяемое решение',color:'blue'},maker:{name:'Инженерия и свой продукт',theme:['technology','science','makers','robotics'],description:'Проблема → прототип → испытание',color:'green'}};
const bases={nearby:{name:'Коста-Рика / Мексика',isos:['CRI','MEX'],route:'local'},latam:{name:'Латинская Америка',isos:['CRI','MEX','BRA','ARG','CHL','COL','PER','PAN','ECU','URY','BOL','GTM','SLV','HND','NIC','DOM','CUB'],route:'southamerica'},eastasia:{name:'Япония / Китай / Тайвань',isos:['JPN','CHN','TWN'],route:'eastasia'},europe:{name:'Европа',isos:['CHE','ESP','FRA','DEU','NLD','BEL','ITA','PRT','GBR','IRL','DNK','SWE','NOR','FIN','AUT','POL','CZE','EST','GRC','ROU','HUN'],route:'europe'},world:{name:'Весь мир',isos:[],route:'destinations'}};
const regions=[['local','Рядом с домом','Коста-Рика / Мексика',['CRI','MEX'],'Ближайший сезон, разные возрастные категории и подготовка команды.','local'],['eastasia','Восточная Азия','Япония / Китай / Тайвань',['JPN','CHN','TWN'],'Английские программы, школьная база и отдельные условия пансиона.','asia'],['europe','Три европейских пути','Швейцария / Испания / Франция',['CHE','ESP','FRA'],'Сравнить язык наставника, лагеря и младший соревновательный путь.','europe'],['southamerica','Латинская Америка','Южная Америка',['BRA','ARG','CHL','COL','PER'],'Национальные лиги, каникулы и язык конкретной программы.','local'],['asia-english','Английская Азия','Сингапур / Гонконг',['SGP','HKG'],'Школа и технический английский проверяются отдельно.','asia'],['southeastasia','Юго-Восточная Азия','Четыре семейных направления',['MYS','IDN','VNM','PHL'],'Программы для короткой пробы и пути младших команд.','asia'],['europe-north','Северная Европа','Германия / Нидерланды / Бельгия',['DEU','NLD','BEL'],'Школьные категории, местная команда и международные квоты.','europe'],['europe-south','Южная Европа','Италия / Португалия',['ITA','PRT'],'Дневные занятия, каникулы и подтверждённый язык курса.','europe'],['middleeast','Ближний Восток','ОАЭ / Оман / Катар / Саудовская Аравия',['ARE','OMN','QAT','SAU'],'Английская школа, младшая команда и технологические события.','world'],['africa','Африка','Шесть проверяемых направлений',['KEN','GHA','NGA','RWA','ZAF','MAR'],'Учебные программы и результаты с точным указанием этапа.','world']];
const focusRoutes={local:data.completeness_audit.local_focus,southamerica:data.completeness_audit.south_america_focus,eastasia:data.east_asia_focus,europe:data.europe_focus,'asia-english':data.asia_english_focus,southeastasia:data.southeast_asia_focus,'europe-north':data.north_europe_focus,'europe-south':data.south_europe_focus,middleeast:data.middleeast_focus,africa:data.africa_focus};
for(const r of regions){const f=focusRoutes[r[0]];const isos=f?.isos||f?.countries?.map(c=>c.iso);if(isos?.length)r[3]=isos;}
bases.latam.isos=data.countries.filter(c=>['Центральная Америка','Южная Америка','Карибский регион'].includes(c.region)||c.iso==='MEX').map(c=>c.iso);
bases.europe.isos=data.countries.filter(c=>c.region.includes('Европа')).map(c=>c.iso);
bases.usa={name:'США',isos:['USA'],route:'strategy'};
bases.asia={name:'Азия целиком',isos:data.countries.filter(c=>c.region.includes('Азия')).map(c=>c.iso),route:'destinations'};
const regionNames=Object.fromEntries(regions.map(r=>[r[0],r[2]]));regionNames.taiwan='Тайвань';
let plan={child:'both',goal:'season',track:'robot',base:'nearby',target:'',done:{}};
function validPlan(raw){const out={child:['both','mat','osc'].includes(raw?.child)?raw.child:'both',goal:Object.hasOwn(goals,raw?.goal)?raw.goal:'season',track:Object.hasOwn(tracks,raw?.track)?raw.track:'robot',base:Object.hasOwn(bases,raw?.base)?raw.base:'nearby',target:typeof raw?.target==='string'?raw.target.slice(0,200):'',done:{}};if(raw?.done&&typeof raw.done==='object')for(const [k,v]of Object.entries(raw.done)){if(/^(both|mat|osc)\|(season|skills|camp|school)\|(robot|ai|maker)\|(nearby|latam|eastasia|europe|world|usa|asia)$/.test(k)&&Array.isArray(v))out.done[k]=[...new Set(v.filter(x=>['brief','coach','gate','build','test','proof'].includes(x)))];}return out;}
try{plan=validPlan(JSON.parse(localStorage.getItem(key)||'null'));}catch{}
window.syncFamilyTrackFromURL=function(){const params=new URLSearchParams(location.search);for(const k of ['child','goal','track','base'])if(params.has(k))plan=validPlan({...plan,[k]:params.get(k)});};window.syncFamilyTrackFromURL();
const combo=()=>[plan.child,plan.goal,plan.track,plan.base].join('|');
const completed=()=>new Set(plan.done[combo()]||[]);
function persist(){try{localStorage.setItem(key,JSON.stringify(plan));}catch{notify('Отметки сохранятся только до закрытия страницы. Можно скачать план.');}const url=new URL(location.href);if(['child','goal','track','base'].some(k=>url.searchParams.has(k))){for(const k of ['child','goal','track','base'])url.searchParams.set(k,plan[k]);history.replaceState(null,'',url.toString());}}
const childName=()=>plan.child==='both'?'Матвей и Оскар':plan.child==='mat'?'Матвей':'Оскар';
const currentChildren=()=>plan.child==='both'?['mat','osc']:[plan.child];
const isNo=v=>/^Нет/i.test(v||'');
function matchesChild(e){return currentChildren().every(k=>!isNo(e[k]));}
function matchesBase(e){return !bases[plan.base].isos.length||e.iso.some(i=>bases[plan.base].isos.includes(i));}
const dateLabel=e=>e.start?dateText(e):e.participation==='regular'?'Регулярный курс · расписание в карточке':'Следующий набор / дата уточняются';
function candidateEvents(){const kind=plan.goal==='season'?'Соревнования':'Лагеря';return events.filter(e=>e.block===kind&&!/^P4/.test(e.priority)&&matchesChild(e)&&matchesBase(e)&&(!e.start||e.end>=TODAY)&&e.themes.some(t=>tracks[plan.track].theme.includes(t))).sort((a,b)=>score(b)-score(a)||a.title.localeCompare(b.title)).slice(0,3);}
function score(e){let v=0;if(['primary','bilingual'].includes(e.language_mode))v+=8;if(e.language_mode==='support')v+=3;if(e.evidence_level==='catalog')v-=8;if(/^P[01]/.test(e.priority))v+=5;if(e.start&&e.end>=TODAY)v+=2;if(plan.goal==='skills'&&e.participation==='regular')v+=5;if(plan.goal==='camp'&&e.participation==='regular')v-=5;if(currentChildren().every(k=>/^(Да|Explore|Junior)/i.test(e[k]||'')))v+=3;return v;}
function candidateSchools(){return schools.filter(s=>(!bases[plan.base].isos.length||bases[plan.base].isos.includes(s.iso))&&currentChildren().every(k=>s.fit[k]==='candidate')).sort((a,b)=>Number(b.instruction_languages.includes('EN'))-Number(a.instruction_languages.includes('EN'))||a.priority-b.priority||a.id.localeCompare(b.id)).slice(0,3);}
function tasks(){const mat=plan.child!=='osc';let project=plan.track==='robot'?(mat?'автономную миссию с датчиком и собственным кодом':'механизм с датчиком и понятной самостоятельной ролью'):plan.track==='ai'?(mat?'программу с данными, тестами и объяснимым результатом':'небольшую игру или алгоритм с понятными входом и выходом'):(mat?'полезный прототип для конкретного пользователя':'действующий механизм для простой бытовой задачи');
if(plan.child==='both'){const younger=plan.track==='robot'?'механизм с датчиком и понятной самостоятельной ролью':plan.track==='ai'?'небольшую игру или алгоритм с понятными входом и выходом':'действующий механизм для простой бытовой задачи';project='для Матвея — '+project+'; для Оскара — '+younger;}
const coach=plan.goal==='school'?['Школа и младший наставник','Проверить места обоим, недельные часы робототехники, тренера и доступ к лаборатории.']:['Диагностика уровня','Показать прошлые проекты тренеру, выбрать следующую сложную задачу и согласовать язык занятий.'];
const gate=plan.goal==='camp'?['Смена и условия поездки','Уточнить даты, возраст, технический язык, внешний приём, проживание и доступное место.']:plan.goal==='school'?['Приём и полная смета','Сверить класс, языковые требования, семейное проживание и все обязательные платежи.']:['Правила выбранной категории','Сверить точный класс, возрастную отсечку, состав команды, оборудование и национальный допуск.'];
return[{id:'brief',title:'Определить самостоятельную роль',detail:plan.child==='both'?'У каждого ребёнка свой вклад и задача по уровню. Совместная команда — только если допускают правила.':'Описать, что ребёнок делает сам и чему хочет научиться в этом сезоне.',period:'Неделя 1'}, {id:'coach',title:coach[0],detail:coach[1],period:'Недели 1–2'}, {id:'gate',title:gate[0],detail:gate[1],period:'До заявки / поездки'}, {id:'build',title:'Собрать рабочий проект',detail:'Предлагаемая задача: '+project+'. Сохранять версии и объяснять принятые решения.',period:'Недели 3–6'}, {id:'test',title:'Проверить в реальных условиях',detail:'Измерить результат, записать неудачи и провести повторный тест. Для командного сезона — полноценный пробный запуск по правилам.',period:'Недели 7–10'}, {id:'proof',title:'Зафиксировать результат и следующий шаг',detail:'Код, фото конструкции, короткое видео, журнал испытаний и объяснение ребёнка. Награду связывать с официальным протоколом и конкретным этапом.',period:'Недели 11–12'}];}
function leagueRoadmap(){return `<section class="ux-league-roadmap"><div class="ux-journey-heading"><div><p class="section-kicker">ВОЗРАСТ → КАТЕГОРИЯ → ОТБОР</p><h3>Лиги на каждом этапе</h3><p>Раскройте возрастной шаг: что сделать самостоятельно, какую лигу проверить и что требуется для перехода.</p></div><button class="button secondary" data-view="leagues">Все лиги и правила ↗</button></div><div class="ux-roadmap-children">${currentChildren().map(k=>{const c=data.development_routes.children.find(x=>x.id===k);return `<article><h4>${safe(c.name)}</h4><p>${safe(c.intro)}</p><ol>${c.stages.map((step,i)=>`<li><details ${i===0?'open':''}><summary><span>${safe(step.age)} лет</span><b>${safe(step.title)}</b><em>＋</em></summary><p>${safe(step.goal)}</p><div class="ux-roadmap-leagues">${step.leagues.filter(id=>profiles.some(p=>p.id===id)).map(id=>`<button data-ux-league="${safe(id)}">${safe(profiles.find(p=>p.id===id).name)} ↗</button>`).join('')}</div><p><strong>Результат:</strong> ${safe(step.deliverable)}</p><p class="ux-roadmap-gate"><strong>Переход:</strong> ${safe(step.gate)}</p></details></li>`).join('')}</ol></article>`;}).join('')}</div></section>`;}
function blueprint(){return `<div class="motion-lab" aria-label="Интерактивный инженерный путь"><svg class="ux-blueprint" viewBox="0 0 620 260" role="img" aria-label="Путь: идея, робот, испытание и свой результат"><defs><pattern id="ux-blueprint-grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="#cbded8" stroke-width=".7"/></pattern><linearGradient id="ux-path-gradient"><stop stop-color="#f28b56"/><stop offset="1" stop-color="#7bb9b0"/></linearGradient></defs><rect width="620" height="260" rx="22" fill="url(#ux-blueprint-grid)"/><path class="ux-drawn-path" d="M55 175C150 175 125 66 230 66S295 183 385 183 445 79 552 79" fill="none" stroke="url(#ux-path-gradient)" stroke-width="3" stroke-dasharray="8 9"/><path class="motion-route-trace" d="M55 175C150 175 125 66 230 66S295 183 385 183 445 79 552 79" stroke-dasharray="0 1000"/><g fill="#142f3d"><circle class="motion-node active" cx="55" cy="175" r="7"/><circle class="motion-node" cx="230" cy="66" r="7"/><circle class="motion-node" cx="385" cy="183" r="7"/><circle class="motion-node" cx="552" cy="79" r="7"/></g><g class="ux-robot-drawing"><rect x="264" y="100" width="95" height="66" rx="15" fill="#fffaf0" stroke="#214b52" stroke-width="3"/><rect x="274" y="110" width="75" height="34" rx="9" fill="#dcece7"/><circle class="motion-eye" cx="294" cy="127" r="5" fill="#214b52"/><circle class="motion-eye" cx="329" cy="127" r="5" fill="#214b52"/><path d="M304 153h15M312 100V86M260 116l-20 17M364 116l20 17" fill="none" stroke="#214b52" stroke-width="3" stroke-linecap="round"/><circle cx="312" cy="83" r="5" fill="#f28b56"/><circle cx="284" cy="176" r="10" fill="#214b52"/><circle cx="340" cy="176" r="10" fill="#214b52"/></g><g font-family="system-ui,sans-serif" font-size="12" fill="#385d62"><text x="34" y="205">ИДЕЯ</text><text x="195" y="43">СОБРАТЬ</text><text x="347" y="214">ПРОВЕРИТЬ</text><text x="506" y="55">ОБЪЯСНИТЬ</text></g><g fill="#f28b56"><path d="m70 57 4 9 9 4-9 4-4 9-4-9-9-4 9-4Z"/><path d="m519 183 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/></g><g class="motion-token" transform="translate(55 175)"><circle r="19"/><circle r="7"/></g></svg><div class="motion-scene-controls" role="group" aria-label="Выбрать этап инженерного пути">${['Идея','Сборка','Тест','Защита'].map((n,i)=>`<button data-motion-stage="${i}" aria-pressed="${i===0}">${n}</button>`).join('')}</div><div class="motion-stage-description" aria-live="polite" aria-atomic="true"><strong class="motion-stage-title">01 · Идея</strong><span class="motion-stage-copy">Выбрать задачу и понять, кому пригодится решение.</span></div><div class="motion-scene-footer"><small>Схема практики · выберите этап</small><button data-motion-play aria-pressed="false">▷ Показать цикл</button></div></div>`;}
function eventChoice(e){const mode=['primary','bilingual'].includes(e.language_mode)?'Язык курса подтверждён':e.language_mode==='support'?'Языковая помощь · основной язык уточнить':'Язык и допуск — в карточке';return `<article class="ux-choice"><div class="ux-choice-top"><span>${safe(e.country)}</span><span>${safe(e.block==='Соревнования'?'Сезон':'Обучение')}</span></div><h4>${safe(e.title)}</h4><p class="ux-choice-date">${safe(dateLabel(e))}</p><p>${safe(mode)}</p><div class="kid-chips">${currentChildren().map(k=>kidChip(e,k,k==='mat'?'Матвей':'Оскар')).join('')}</div><div class="ux-choice-actions"><button class="button secondary" data-open="${e.id}">Условия ↗</button><button data-favorite="${e.id}" aria-pressed="${favoriteIds.has(e.id)}" aria-label="${favoriteIds.has(e.id)?'Убрать из планов':'В планы'}: ${safe(e.title)}">${favoriteIds.has(e.id)?'✓ В планах':'＋ В планы'}</button></div></article>`;}
function schoolChoice(s){return `<article class="ux-choice"><div class="ux-choice-top"><span>${safe(s.country)}</span><span>Школа</span></div><h4>${safe(s.name)}</h4><p>${safe(s.ages)}</p><p>Язык ступени: ${safe(s.instruction_languages.join(' / '))}. Младшую команду и место проверить отдельно.</p><button class="button secondary" data-ux-school="${s.id}">Досье и источники ↗</button></article>`;}
window.renderFamilyJourney=function(){const root=q('#journey-content');if(!root)return;const done=completed(),choices=plan.goal==='school'?candidateSchools():candidateEvents();const percent=Math.round(done.size/6*100);const children=plan.child==='both'?Object.values(data.family_strategy.children):[data.family_strategy.children[plan.child]];
root.innerHTML=`<header class="ux-journey-intro"><div><p class="section-kicker">СЕМЕЙНАЯ МАСТЕРСКАЯ</p><h3>Цель становится<br><em>маршрутом.</em></h3><p>Выберите задачу для Матвея, Оскара или обоих. Соберите план практики, проверьте условия и отмечайте свои шаги.</p><span class="ux-editorial">Предлагаемый план · места и допуск отдельно</span></div>${blueprint()}</header>
<section class="ux-planner" aria-label="Настроить семейный трек"><div class="ux-planner-heading"><h3>1. Настроить трек</h3><span>Можно менять в любой момент</span></div><div class="ux-child-tabs" role="group" aria-label="Для кого строим трек">${[['both','Вместе','Две самостоятельные роли'],['mat','Матвей','2017 · 9 лет'],['osc','Оскар','2020 · 6 лет']].map(([id,n,age])=>`<button data-ux-child="${id}" aria-pressed="${id===plan.child}"><span>${safe(n)}</span><small>${safe(age)}</small></button>`).join('')}</div><p class="ux-control-label">Цель ближайшего сезона</p><div class="ux-goal-grid" role="group" aria-label="Цель трека">${Object.entries(goals).map(([id,g])=>`<button data-ux-goal="${id}" aria-pressed="${id===plan.goal}">${icon(g.icon)}<span>${safe(g.name)}</span></button>`).join('')}</div><div class="ux-control-row"><label>Направление<select id="ux-track-select">${Object.entries(tracks).map(([id,t])=>`<option value="${id}" ${id===plan.track?'selected':''}>${safe(t.name)}</option>`).join('')}</select></label><label>Где искать среду<select id="ux-base-select">${Object.entries(bases).map(([id,b])=>`<option value="${id}" ${id===plan.base?'selected':''}>${safe(b.name)}</option>`).join('')}</select></label></div><label class="ux-target-label">Своя цель в одном предложении<input id="ux-target-input" type="text" maxlength="200" value="${safe(plan.target)}" placeholder="Например: самостоятельно собрать робота и пройти местный сезон"></label></section>
<section class="ux-plan-summary ${tracks[plan.track].color}" aria-label="Выбранный маршрут"><div><p class="section-kicker">${safe(childName().toUpperCase())} · ${safe(bases[plan.base].name)}</p><h3>${safe(goals[plan.goal].name)}</h3><p>${safe(goals[plan.goal].intro)}</p><span>${safe(tracks[plan.track].description)}</span></div><div class="ux-progress-ring" style="--progress:${percent*3.6}deg" role="img" aria-label="Ваши отметки: ${done.size} из 6 шагов"><span><b>${done.size}<small>/6</small></b><em>мои шаги</em></span></div></section>
<div class="ux-journey-heading"><div><p class="section-kicker">2. ПРАКТИКА НА 90 ДНЕЙ</p><h3>От следующей задачи<br>к своему результату</h3><p>Темп — предложение для семьи. Отметка означает вашу оценку выполнения шага.</p></div><button class="text-button" data-ux-reset-steps>Сбросить отметки</button></div><div class="ux-task-grid">${tasks().map((t,i)=>`<article class="ux-task ${done.has(t.id)?'done':''}"><div class="ux-task-meta"><span>0${i+1}</span><small>${safe(t.period)}</small></div><h4>${safe(t.title)}</h4><p>${safe(t.detail)}</p><label><input type="checkbox" data-ux-task="${t.id}" aria-label="Отметить шаг: ${safe(t.title)}" ${done.has(t.id)?'checked':''}><span>${done.has(t.id)?'Отмечено мной':'Отметить свой шаг'}</span></label></article>`).join('')}</div>
<section class="ux-child-notes" aria-label="Отдельная роль каждого ребёнка">${children.map(c=>`<article><span class="ux-child-avatar ${c.birth_year===2017?'mat':'osc'}">${safe(c.name.slice(0,1))}</span><div><h4>${safe(c.name)} · самостоятельная роль</h4><p>${safe(c.detail)}</p><details><summary>Что считать результатом сезона</summary><p>${safe(c.proof)}</p></details></div></article>`).join('')}</section>
<div class="ux-journey-heading"><div><p class="section-kicker">3. СРЕДА ДЛЯ ЭТОГО ТРЕКА</p><h3>Карточки, с которых начать проверку</h3><p>Редакционный подбор по территории, возрастным ограничениям и языковым доказательствам. Новая заявка ещё не принята.</p></div><button class="button secondary" data-ux-find>Все варианты ↗</button></div><div class="ux-choice-grid">${choices.length?choices.map(x=>plan.goal==='school'?schoolChoice(x):eventChoice(x)).join(''):`<div class="ux-no-choice"><h4>Точного сочетания пока нет</h4><p>Расширьте регион или откройте все варианты. Неизвестный допуск не превращён в подтверждённое место.</p><button class="button secondary" data-ux-find>Открыть каталог ↗</button></div>`}</div>
<section class="ux-horizon"><div><p class="section-kicker">4. ГОРИЗОНТ РАЗВИТИЯ</p><h3>Следующий сезон —<br>часть большего пути.</h3><p>План навыков на 10–12 лет. Возрастные категории, оборудование, отбор и будущие даты перепроверяются каждый сезон.</p></div><ol>${[['2026–2028','Своя роль и регулярная команда','Самостоятельная сборка, код, испытания и объяснение решения.'],['2028–2031','Инженерная глубина','Датчики, CAD, электроника, Python / C++. Команда братьев — если допускают правила.'],['2031–2034','Сильная команда и реальные задачи','Более сложная лига по возрасту, лаборатория и проект с реальным пользователем.'],['2034–2038','Специализация и свой продукт','Углублять интерес, проверять спрос и собирать портфолио созданных решений.']].map(([period,title,detail],i)=>`<li><span>0${i+1}</span><div><small>${period}</small><h4>${title}</h4><p>${detail}</p></div></li>`).join('')}</ol></section>
${leagueRoadmap()}
${window.nearbyParticipationMarkup?.()||''}
<section class="ux-plan-tools"><div><h3>Продолжить вместе</h3><p>Отметки и избранное хранятся в этом браузере. Файл плана переносит их на устройство жены; ссылка переносит только настройки трека.</p></div><div><button class="button primary" data-ux-export>Скачать план</button><button class="button secondary" data-ux-import>Открыть файл плана</button><button class="button secondary" data-ux-share>Ссылка на этот трек</button><button class="button secondary" data-ux-route="${bases[plan.base].route}">Гид по направлению ↗</button><input id="ux-plan-file" type="file" accept="application/json,.json" hidden></div></section>`;
};
window.renderAtlasDestinations=function(){q('#destinations-content').innerHTML=`<header class="ux-destinations-head"><div><p class="section-kicker">СТРАНЫ · СВОЯ ЗАДАЧА В КАЖДОЙ</p><h3>Начать рядом.<br><em>Расти по всему миру.</em></h3><p>Выберите направление: внутри — возраст, язык, школьная среда, лагеря и путь в соревнования.</p></div><div class="ux-coverage-orb"><b>${data.coverage_summary.countries_with_records}</b><span>стран и территорий<br>с конкретными записями</span><small>из ${data.coverage_summary.countries} · частичный охват</small></div></header><div class="ux-region-grid">${regions.map(([route,kicker,name,isos,description,tone],i)=>{const n=events.filter(e=>e.iso.some(x=>isos.includes(x))).length,ns=schools.filter(s=>isos.includes(s.iso)).length;return `<article class="ux-region-card ${tone}"><div class="ux-region-art"><svg viewBox="0 0 260 110" aria-hidden="true"><path d="M10 90Q60 15 110 60T250 25" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="5 7"/><circle cx="45" cy="56" r="17" fill="currentColor" opacity=".12"/><circle cx="45" cy="56" r="4" fill="currentColor"/><circle cx="151" cy="71" r="25" fill="currentColor" opacity=".12"/><circle cx="151" cy="71" r="5" fill="currentColor"/><circle cx="222" cy="40" r="4" fill="currentColor"/></svg><span>${String(i+1).padStart(2,'0')}</span></div><div><p class="section-kicker">${safe(kicker)}</p><h4>${safe(name)}</h4><p>${safe(description)}</p><p class="ux-region-countries">${isos.map(countryName).map(safe).join(' · ')}</p><div class="ux-region-counts"><span>${n} карточек</span><span>${ns} школьных досье</span></div><button class="button secondary" data-ux-route="${route}">Открыть маршрут ↗</button></div></article>`}).join('')}</div><div class="ux-destinations-footer"><p>Числа показывают записи этой базы. Полный местный аудит всех стран ещё продолжается.</p><button class="button secondary" data-view="map">Открыть карту мира ↗</button><button class="button secondary" data-view="about">Источники и охват ↗</button></div>`;};
function renderHome(){const due=events.filter(e=>/^P[01]/.test(e.priority)&&e.deadline>=TODAY&&e.deadline<=addDays(TODAY,30)&&!/^P4/.test(e.priority)).sort((a,b)=>a.deadline.localeCompare(b.deadline)).slice(0,3);q('#ux-home').innerHTML=`<div class="ux-start-heading"><p class="section-kicker">НЕ ПРОПУСТИТЬ СВОЙ СЕЗОН</p><h2>С чего начнём?</h2><span>${events.length.toLocaleString('ru-RU')} карточки · ${schools.length} школы · ${profiles.length} профилей</span></div><div class="ux-start-grid">${[['journey','arrow','Собрать трек','Цель и практика для каждого ребёнка','orange'],['catalog','trophy','Найти соревнование','Возраст, категория, команда и отбор','blue'],['camps','sun','Спланировать каникулы','Язык, проект, смена и проживание','green'],['schools','book','Выбрать среду','Школа, наставник и лаборатория','navy']].map(([view,ic,title,detail,tone])=>`<button class="ux-start-card ${tone}" data-view="${view}">${icon(ic)}<b>${title}</b><span>${detail}</span><em>↗</em></button>`).join('')}</div>${due.length?`<section class="ux-horizon-soon"><div><p class="section-kicker">БЛИЖАЙШИЕ СРОКИ</p><h3>Сначала проверить<br>эти даты.</h3><button class="text-button" data-view="calendar">Весь календарь ↗</button></div><div class="ux-due-list">${due.map(e=>`<button data-open="${e.id}"><span>${shortDate(e.deadline)}</span><div><b>${safe(e.title)}</b><small>${safe(e.country)} · срок заявки / проверки</small></div><em>↗</em></button>`).join('')}</div></section>`:''}`;}
function effectiveRoute(){const h=location.hash.slice(1);return regionNames[h]?h:state.view;}
window.refreshAtlasUX=function(){const r=effectiveRoute(),regional=!!regionNames[r];document.body.dataset.uxView=r;document.body.classList.toggle('ux-regional',regional);document.body.classList.add('ux-ready');q('#ux-home').hidden=state.view!=='explore';if(state.view==='explore')renderHome();if(regional){q('#view-label').textContent=regionNames[r];q('#section-title').textContent=regionNames[r];q('#section-kicker').textContent='РЕГИОНАЛЬНЫЙ МАРШРУТ';let bar=q('#ux-region-jumps');if(!bar){bar=document.createElement('nav');bar.id='ux-region-jumps';bar.className='ux-region-jumps';bar.setAttribute('aria-label','Разделы регионального маршрута');q('#audit-body').before(bar);}bar.innerHTML=`<button data-ux-route="destinations">← Направления</button>${[['.taiwan-intro','Обзор'],['.europe-probe','Цель поездки'],['.europe-family-picks','С чего начать'],['.europe-routes','Страны и условия'],['.europe-plan','Следующие шаги']].filter(([sel])=>q('#audit-body '+sel)).map(([sel,name])=>`<button data-ux-scroll="${sel}">${name}</button>`).join('')}`;}else q('#ux-region-jumps')?.remove();qa('#navigation .nav-item,#ux-mobile-nav [data-view]').forEach(b=>{const active=b.dataset.view===r||b.dataset.uxRoute===r;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(regional)q('.nav-regions').open=true;q('.category-row').hidden=state.view!=='explore';q('.best-entry').hidden=state.view!=='explore';q('.school-home-link').hidden=state.view!=='explore';q('.ux-sidebar-shade').hidden=!q('.sidebar').classList.contains('open');q('[data-ux-back-top]').hidden=window.scrollY<900;icons();};
document.addEventListener('stem:render',window.refreshAtlasUX);
function closeDrawer(){q('.sidebar').classList.remove('open');q('.page-shell').inert=false;document.body.classList.remove('ux-menu-open');q('#menu-button').setAttribute('aria-expanded','false');q('.ux-sidebar-shade').hidden=true;requestAnimationFrame(()=>q('#menu-button').focus({preventScroll:true}));}
function motion(){return matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';}
function scrollView(){requestAnimationFrame(()=>{const el=state.view==='explore'?q('#hero'):q('.workspace');el.scrollIntoView({behavior:motion(),block:'start'});q('#section-title').tabIndex=-1;if(state.view!=='explore')q('#section-title').focus({preventScroll:true});});}
function navigate(route){if(regionNames[route]){if(location.hash!=='#'+route)history.pushState(null,'','#'+route);applyLocationRoute();q('.sidebar').classList.remove('open');q('#menu-button').setAttribute('aria-expanded','false');q('.ux-sidebar-shade').hidden=true;}else setView(route);scrollView();}
function findAll(){if(plan.goal==='school'){navigate('schools');window.focusAtlasSchools(bases[plan.base].isos,bases[plan.base].name,plan.child);return;}navigate('catalog');Object.assign(state,{best:false,league:'',block:plan.goal==='season'?'Соревнования':'Лагеря',routeIsos:[...bases[plan.base].isos],country:'',region:'',kid:plan.child==='both'?'':plan.child,query:'',theme:plan.track==='robot'?'robotics':plan.track==='ai'?'coding':'',language:'',languageMode:'',scope:'',participation:'',admission:'',evidence:'',dates:'',priority:false,excluded:true,limit:12});render();}
function openSchool(id){window.openAtlasSchool(id);}
function downloadJSON(){const payload={app:'STEM Atlas family plan',version:1,exported_at:new Date().toISOString(),research_asof:data.asof,plan:validPlan(plan),favorite_ids:Array.from(favoriteIds),note:'Личные отметки о шагах. Не подтверждение регистрации, оплаты, школьного места или награды.'};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='STEM_family_plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function importJSON(file){try{if(!file||file.size>512000)throw Error();const raw=JSON.parse(await file.text());if(raw.app!=='STEM Atlas family plan'||raw.version!==1||!raw.plan)throw Error();plan=validPlan(raw.plan);if(Array.isArray(raw.favorite_ids))raw.favorite_ids.filter(id=>events.some(e=>e.id===id)).forEach(id=>favoriteIds.add(id));persist();try{localStorage.setItem('stemAtlasFavorites.v1',JSON.stringify([...favoriteIds]));}catch{}render();notify('План перенесён. Существующее избранное сохранено.');}catch{notify('Не удалось открыть план. Выберите JSON-файл, скачанный из этого атласа.');}}
function shareTrack(){const url=new URL(location.href);url.search='';url.hash='journey';for(const k of ['child','goal','track','base'])url.searchParams.set(k,plan[k]);history.replaceState(null,'',url.toString());const payload=url.toString();if(navigator.clipboard?.writeText)navigator.clipboard.writeText(payload).then(()=>notify('Ссылка скопирована. Она передаёт настройки, без личных отметок.')).catch(()=>showShareURL(payload));else showShareURL(payload);}
function showShareURL(url){const tools=q('.ux-plan-tools');let box=q('#ux-share-url');if(!box){box=document.createElement('input');box.id='ux-share-url';box.readOnly=true;box.setAttribute('aria-label','Ссылка на выбранный трек');tools.append(box);}box.value=url;box.focus();box.select();notify('Скопируйте выделенную ссылку.');}
let searchType='all',searchIndex=-1,lastSearchFocus;
const normalize=s=>String(s).toLocaleLowerCase('ru').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ё/g,'е');
const index=[...events.map(e=>({id:e.id,type:e.block==='Соревнования'?'competition':e.block==='Лагеря'?'camp':'event',title:e.title,detail:e.country+' · '+(e.city||e.age),search:normalize([e.id,e.title,e.country,e.city,e.age,e.themes.map(t=>({robotics:'робототехника robot',ai:'ИИ AI',coding:'код programming',technology:'технологии STEM',science:'наука'}[t]||t))].join(' '))})),...schools.map(s=>({id:s.id,type:'school',title:s.name,detail:s.country+' · '+s.ages,search:normalize([s.id,s.name,s.country,s.city,s.curriculum].join(' '))})),...profiles.map(p=>({id:p.id,type:'league',title:p.name,detail:p.age_summary,search:normalize([p.id,p.name,p.summary,p.age_summary].join(' '))}))];
const searchTypeNames={all:'Всё',competition:'Соревнования',camp:'Лагеря',school:'Школы',league:'Лиги',event:'Выставки'};
function searchResults(){const text=normalize(q('#ux-search-input').value.trim()),tokens=text.split(/\s+/).filter(Boolean);const result=index.filter(x=>(searchType==='all'||x.type===searchType)&&tokens.every(t=>x.search.includes(t))).sort((a,b)=>Number(b.title.toLocaleLowerCase().startsWith(text))-Number(a.title.toLocaleLowerCase().startsWith(text)));const rows=result.slice(0,text?14:6);searchIndex=-1;q('#ux-search-types').innerHTML=Object.entries(searchTypeNames).map(([id,name])=>`<button data-ux-search-type="${id}" aria-pressed="${id===searchType}">${name}</button>`).join('');q('#ux-search-count').textContent=text?`${result.length} совпадений · показано ${rows.length}`:'Начните вводить название, страну или тему';q('#ux-search-results').innerHTML=(!text&&searchType==='all'?`<div class="ux-search-quick">${[['journey','Мой трек'],['destinations','Направления'],['calendar','Календарь'],['saved','Наши планы']].map(([route,name])=>`<button data-ux-search-route="${route}">${name} ↗</button>`).join('')}</div>`:'')+(rows.length?rows.map(x=>`<button class="ux-search-result" data-ux-result="${safe(x.id)}" data-ux-result-type="${x.type}"><span class="ux-search-type ${x.type}">${searchTypeNames[x.type]}</span><div><b>${safe(x.title)}</b><small>${safe(x.detail)}</small></div><em>↗</em></button>`).join(''):'<p class="ux-search-empty">Совпадений нет. Попробуйте страну или короткое название лиги.</p>');}
function openSearch(){lastSearchFocus=document.activeElement;q('#ux-search-dialog').showModal();q('#ux-search-input').value='';searchType='all';searchResults();q('#ux-search-input').focus();}
function closeSearch(){q('#ux-search-dialog').close();lastSearchFocus?.focus({preventScroll:true});}
function openLeague(id){if(!profiles.some(p=>p.id===id))return;Object.assign(leagueState,{tab:'guide',best:false,query:'',group:'',age:''});leagueState.opened.add(id);navigate('leagues');const el=q('#league-'+id);if(el){el.querySelector('details').open=true;el.scrollIntoView({behavior:motion(),block:'start'});el.querySelector('summary')?.focus({preventScroll:true});}}
function searchOpen(id,type){closeSearch();if(type==='school')openSchool(id);else if(type==='league')openLeague(id);else openEvent(id);}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.view)requestAnimationFrame(()=>{scrollView();window.refreshAtlasUX();});if(b.dataset.uxRoute)navigate(b.dataset.uxRoute);if(b.dataset.uxSchool)openSchool(b.dataset.uxSchool);if(b.dataset.uxLeague)openLeague(b.dataset.uxLeague);if(b.dataset.uxScroll)q('#audit-body '+b.dataset.uxScroll)?.scrollIntoView({behavior:motion(),block:'start'});if(b.hasAttribute('data-ux-find'))findAll();if(b.dataset.uxChild){plan.child=b.dataset.uxChild;persist();renderFamilyJourney();q(`[data-ux-child="${plan.child}"]`)?.focus({preventScroll:true});}if(b.dataset.uxGoal){plan.goal=b.dataset.uxGoal;persist();renderFamilyJourney();q(`[data-ux-goal="${plan.goal}"]`)?.focus({preventScroll:true});}if(b.hasAttribute('data-ux-reset-steps')){plan.done[combo()]=[];persist();renderFamilyJourney();q('[data-ux-reset-steps]')?.focus({preventScroll:true});}if(b.hasAttribute('data-ux-export'))downloadJSON();if(b.hasAttribute('data-ux-import'))q('#ux-plan-file').click();if(b.hasAttribute('data-ux-share'))shareTrack();if(b.hasAttribute('data-ux-search'))openSearch();if(b.hasAttribute('data-ux-search-close'))closeSearch();if(b.dataset.uxResult)searchOpen(b.dataset.uxResult,b.dataset.uxResultType);if(b.dataset.uxSearchRoute){closeSearch();navigate(b.dataset.uxSearchRoute);}if(b.dataset.uxSearchType){searchType=b.dataset.uxSearchType;searchResults();q(`[data-ux-search-type="${searchType}"]`).focus();}if(b.hasAttribute('data-ux-menu')){q('#menu-button').click();q('.ux-sidebar-shade').hidden=!q('.sidebar').classList.contains('open');}if(b.id==='menu-button')q('.ux-sidebar-shade').hidden=!q('.sidebar').classList.contains('open');if(b.hasAttribute('data-ux-close-menu'))closeDrawer();if(b.hasAttribute('data-ux-back-top'))scrollView();if(b.dataset.auditTab){const route=regionNames[b.dataset.auditTab]?b.dataset.auditTab:'about';if(location.hash!=='#'+route)history.pushState(null,'','#'+route);window.refreshAtlasUX();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.uxTask){const done=completed();t.checked?done.add(t.dataset.uxTask):done.delete(t.dataset.uxTask);plan.done[combo()]=[...done];persist();const id=t.dataset.uxTask;renderFamilyJourney();q(`[data-ux-task="${id}"]`)?.focus({preventScroll:true});}if(t.id==='ux-track-select'||t.id==='ux-base-select'){plan[t.id==='ux-track-select'?'track':'base']=t.value;persist();renderFamilyJourney();q('#'+t.id)?.focus({preventScroll:true});}if(t.id==='ux-plan-file')importJSON(t.files?.[0]);});
document.addEventListener('input',e=>{if(e.target.id==='ux-target-input'){plan.target=e.target.value.slice(0,200);persist();}if(e.target.id==='ux-search-input')searchResults();});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();q('#ux-search-dialog').open?closeSearch():openSearch();}if(e.key==='Tab'&&q('.sidebar').classList.contains('open')&&matchMedia('(max-width:720px)').matches){const nodes=qa('.sidebar a,.sidebar button,.sidebar summary').filter(el=>el.getClientRects().length);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.key==='Escape'&&q('.sidebar').classList.contains('open'))closeDrawer();if(q('#ux-search-dialog').open&&['ArrowDown','ArrowUp','Enter'].includes(e.key)&&(document.activeElement.id==='ux-search-input'||document.activeElement.matches('.ux-search-result'))){const rows=qa('.ux-search-result');if(!rows.length)return;e.preventDefault();if(e.key==='Enter'){if(searchIndex>=0)rows[searchIndex].click();else rows[0].click();return;}searchIndex=(searchIndex+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length;rows.forEach((r,i)=>r.classList.toggle('selected',i===searchIndex));rows[searchIndex].focus({preventScroll:true});rows[searchIndex].scrollIntoView({block:'nearest'});}});
q('.ux-sidebar-shade')?.addEventListener('click',closeDrawer);
q('#ux-search-dialog')?.addEventListener('click',e=>{if(e.target===q('#ux-search-dialog'))closeSearch();});
q('#ux-search-dialog')?.addEventListener('cancel',()=>lastSearchFocus?.focus({preventScroll:true}));
window.addEventListener('resize',()=>{if(innerWidth>720&&q('.sidebar').classList.contains('open'))closeDrawer();});
window.addEventListener('scroll',()=>{q('[data-ux-back-top]').hidden=window.scrollY<900;},{passive:true});
new MutationObserver(()=>{const on=q('.sidebar').classList.contains('open')&&matchMedia('(max-width:720px)').matches;q('.ux-sidebar-shade').hidden=!on;q('.page-shell').inert=on;document.body.classList.toggle('ux-menu-open',on);if(on)q('.sidebar [data-ux-close-menu]')?.focus();}).observe(q('.sidebar'),{attributes:true,attributeFilter:['class']});
})();
